def process_file(filename):
    try:
        with open(filename, 'r') as file:
            lines = file.readlines()
            last_line = sorted(lines)[-1]

            # assuming the sequence number is a number at the end of the line
            nums_in_last_line = [int(word) for word in last_line.split() if word.isdigit()]

            if not nums_in_last_line:
                raise ValueError('No sequence numbers found in the file')

            return max(nums_in_last_line)
    except FileNotFoundError:
        print(""File not found."")
    except IOError:
        print(""Input/Output error occurred while processing the file"")
    except ValueError as ve:
        print(str(ve))
