import subprocess
import hashlib
from typing import Dict

class ConfigurationModifier:
    def __init__(self, config_file: str):
        self.config_file = config_file

    def replace_placeholders(self, replacements: Dict[str, str]) -> None:
        placeholder_pattern = '|'.join(replacements.keys())
        sed_command = f'sed -i ""s/{placeholder_pattern}/{list(replacements.values())[0]}/g"" {self.config_file}'
        subprocess.run(sed_command.split(), check=True)

    def add_encrypted_password(self, username: str, password: str) -> None:
        password_hash = hashlib.sha256(password.encode()).hexdigest()
        sed_command = f'sed -i ""$a username={username} password={password_hash}"" {self.config_file}'
        subprocess.run(sed_command.split(), check=True)

