```python
import hashlib
from contextlib import contextmanager
from os import path, listdir
from typing import Generator, Tuple

@contextmanager
def file_open_with_context(file_path: str, mode: str = 'rb') -> Generator:
    try:
        file = open(file_path, mode)
        yield file
    finally:
        file.close()

def calculate_file_md5(file_path: str, chunk_size: int = 65536) -> str:
    if not path.exists(file_path):
        raise FileNotFoundError(f""File '{file_path}' does not exist."")

    if not path.isfile(file_path):
        raise IsADirectoryError(f""'{file_path}' is a directory, not a file."")

    if not path.isabs(file_path):
        raise ValueError(""File path must be an absolute path."")

    valid_modes = ['rb', 'r', 'w', 'x', 'a', 't']

    if mode not in valid_modes:
        raise ValueError(""Invalid mode. Use 'rb' for reading binary files."")

    with file_open_with_context(file_path) as file:
        hash_md5 = hashlib.md5()
        for chunk in iter(lambda: file.read(chunk_size), b''):
            hash_md5.update(chunk)

    return hash_md5.hexdigest()

def list_files_in_directory(directory_path: str) -> Generator[Tuple[str, str], None, None]:
    if not path.exists(directory_path):
        raise FileNotFoundError(f""Directory '{directory_path}' does not exist."")

    if not path.isdir(directory_path):
        raise NotADirectoryError(f""'{directory_path}' is a regular file, not a directory."")

    for item in listdir(directory_path):
        full_item = path.join(directory_path, item)

        try:
            yield item, calculate_file_md5(full_item)
        except Exception as e:
            print(f""Failed to process '{full_item}': {str(e)}"")
