class ShellCommandAnalyzer:
    def __init__(self):
        self.random_data = []

    def generate_random_data(self, n):
        self.random_data = [random.randint(1, 100) for _ in range(n)]
        return self.random_data

    def calculate_std_dev(self):
        return np.std(self.random_data)

    def filter_by_threshold(self, min_val=None, max_val=None):
        if min_val is not None:
            self.random_data = [x for x in self.random_data if x >= min_val]
        if max_val is not None:
            self.random_data = [x for x in self.random_data if x <= max_val]
        return self.random_data

    def plot_distribution(self):
        plt.hist(self.random_data)
        plt.show()

    def execute_shell_command(self, command):
        process = subprocess.Popen(command.split(), stdout=subprocess.PIPE)
        output, error = process.communicate()
        return output.decode('utf-8') if not error else ""Error occurred while executing the shell command.""
