import os
import hashlib

class ConfigurationModifier:
    def __init__(self, config_file):
        self.config_file = config_file

    def replace_placeholders(self, dict_to_replace):
        pattern = '|'.join(f'({k})' for k in dict_to_replace.keys())
        replacement = list(dict_to_replace.values())[0] # assuming all values are same
        os.system(f""sed -i \'s/{pattern}/{replacement}/\' {self.config_file}"")

    def add_encrypted_password(self, username, password):
        encrypted = hashlib.sha256(password.encode()).hexdigest()  # create SHA256 hash of the password
