import os
import hashlib
from typing import Dict, List

class ConfigurationModifier:
    def __init__(self, config_file):
        self.config_file = config_file

    def replace_placeholders(self, placeholder_dict: Dict[str, str]):
        for placeholder, replacement in placeholder_dict.items():
            os.system('sed -i ""s/' + placeholder + '/' + replacement + '/g"" ' + self.config_file)

    def add_encrypted_password(self, username: str, password: str):
        hashed_password = hashlib.sha256(password.encode()).hexdigest()
        os.system('echo ""' + username + ': ' + hashed_password + '"" >> ' + self.config_file)

class PokemonWeaknessRetriever:
