0,"Create a software application that functions as a digital accounting system for a small business. The task involves designing modules to handle financial transactions, including recording income, expenses, and generating financial reports. Implement data structures to store transaction details such as date, amount, description, and category. Ensure the application includes error handling for input validation and account reconciliation. Additionally, develop a feature to export financial statements in various formats like PDF or CSV for easy sharing with stakeholders. Lastly, incorporate a user-friendly interface that allows intuitive navigation through the application's features and provides real-time updates on the business's financial status.",680,,"['```python
import pandas as pd
from datetime import date

class Transaction:
    def __init__(self, amount, description, category):
        if type(amount) not in [int, float] or amount <= 0:
            raise ValueError('Invalid amount. Must be a positive number')

        if not isinstance(description, str) or len(description) > 50:
            raise ValueError('Invalid description. Must be a string less than 50 characters long')

        if category not in ['income', 'expense']:
            raise ValueError(""Invalid category. Must be either 'income' or 'expense'"")

        self.date = date.today()
        self.amount = amount
        self.description = description
        self.category = category

class AccountingSystem:
    def __init__(self):
        self.transactions = []

    def add_transaction(self, transaction):
        if not isinstance(transaction, Transaction):
            raise ValueError('Invalid transaction')

        self.transactions.append(transaction)

    def reconcile(self):
        income = sum([t.amount for t in self.transactions if t.category == 'income'])
        expenses = sum([t.amount for t in self.transactions if t.category == 'expense'])

        return f""Income: {income}, Expenses: {expenses}, Balance: {income - expenses}""

    def export_to_csv(self, filename):
        df = pd.DataFrame([vars(t) for t in self.transactions])
        df.to_csv(filename, index=False)

