def complex_dict_operations(initial_data, operations):
    modified_dict = initial_data.copy()

    for op in operations:
        operation_type = op[0].lower()

        if operation_type not in ['add', 'remove', 'update']:
            raise ValueError(f""Invalid operation '{operation_type}'"")

        key = op[1]

        if operation_type == ""add"":
            value = None
            if len(op) == 3:
                value = op[2]
            elif len(op) > 3:
                raise ValueError(""Only one or two arguments expected for add operation"")

            modified_dict[key.lower()] = value

        elif operation_type == ""update"":
            if len(op) != 3:
                raise ValueError(""Two arguments expected for update operation"")

            new_value = op[2]
            lowered_keys = list(modified_dict.keys())
            key_in_lowered_case = key.lower()

            if key_in_lowered_case not in lowered_keys:
                raise ValueError(f""Key '{key}' does not exist"")

            actual_key = lowered_keys[lowered_keys.index(key_in_lowered_case)]  # Actual key case-sensitive

            modified_dict[actual_key] = new_value

        elif operation_type == ""remove"":
            if len(op) != 2:
                raise ValueError(""One argument expected for remove operation"")

            lowered_keys = list(modified_dict.keys())
            key_in_lowered_case = key.lower()

            if key_in_lowered_case not in lowered_keys:
                raise ValueError(f""Key '{key}' does not exist"")

            actual_key = lowered_keys[lowered_keys.index(key_in_lowered_case)]  # Actual key case-sensitive

            del modified_dict[actual_key]

    return modified_dict
