```python
from fastapi import FastAPI, Depends, HTTPException, status
from sqlalchemy.orm import Session
import models, schemas, crud
from database import SessionLocal, engine
from jose import JWTError, jwt
from passlib.context import CryptContext
from typing import List, Optional
from fastapi.security import OAuth2PasswordBearer
from pydantic import BaseModel
import os

models.Base.metadata.create_all(bind=engine)
app = FastAPI()
SECRET_KEY = ""mysecretkey""  # Replace with your own secret key
ALGORITHM = ""HS256""
oauth2_scheme = OAuth2PasswordBearer(tokenUrl=""token"")
pwd_context = CryptContext(schemes=[""bcrypt""], deprecated=""auto"")

class TokenData(BaseModel):
    username: str = None

def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

def verify_password(plain_password, hashed_password):
    return pwd_context.verify(plain_password, hashed_password)

def get_current_user(db: Session = Depends(get_db), token: str = Depends(oauth2_scheme)):
    credentials_exception = HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail=""Could not validate credentials"",
        headers={""WWW-Authenticate"": ""Bearer""},
    )
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        username: str = payload.get(""sub"")
        if username is None:
            raise credentials_exception
        token_data = TokenData(username=username)
    except JWTError:
        raise credentials_exception
    user = crud.get_user_by_name(db, username=token_data.username)
    if user is None:
        raise credentials_exception
    return user

@app.post(""/users/"", response_model=schemas.User)
def create_user(user: schemas.UserCreate, db: Session = Depends(get_db)):
    db_user = crud.get_user_by_email(db, email=user.email)
    if db_user:
        raise HTTPException(status_code=400, detail=""Email already registered"")
    return crud.create_user(db=db, user=user)

@app.post(""/login/"", response_model=schemas.User)
def login_for_access_token(form_data: OAuth2PasswordRequestForm = Depends(), db: Session = Depends(get_db)):
    user = authenticate_user(db, form_data.username, form_data.password)
    if not user:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail=""Incorrect username or password"",
            headers={""WWW-Authenticate"": ""Bearer""},
        )
    access_token = create_access_token(data={""sub"": user.username})
    return {""access_token"": access_token, ""token_type"": ""bearer""}

@app.post(""/books/"", response_model=schemas.Book)
def create_book(book: schemas.BookCreate, db: Session = Depends(get_db), current_user: schemas.User = Depends(get_current_user)):
    return crud.create_book(db=db, book=book)

@app.get(""/books/"", response_model=List[schemas.Book])
def read_books(skip: int = 0, limit: int = 100, db: Session = Depends(get_db), current_user: schemas.User = Depends(get_current_user)):
    books = crud.get_books(db, skip=skip, limit=limit)
    return books

@app.put(""/books/{book_id}"", response_model=schemas.Book)
def update_book(book_id: int, book: schemas.BookUpdate, db: Session = Depends(get_db), current_user: schemas.User = Depends(get_current_user)):
    return crud.update_book(db=db, book_id=book_id, book=book)

@app.delete(""/books/{book_id}"", response_model=schemas.Book)
def delete_book(book_id: int, db: Session = Depends(get_db), current_user: schemas.User = Depends(get_current_user)):
    return crud.delete_book(db=db, book_id=book_id)
