import csv
import argparse
import sys

def read_csv(filename):
    try:
        with open(filename) as file:
            reader = csv.reader(file)
            data = [int(row[0]) for row in reader]
        return data
    except FileNotFoundError:
        print(""File not found."")
        sys.exit()
    except ValueError:
        print(""Invalid integer value in the CSV file."")
        sys.exit()
    except Exception as e:
        print(f""Unexpected error occurred: {e}"")
        sys.exit()

def find_maximum(data):
    max_value = data[0]
    for value in data[1:]:
        if value > max_value:
            max_value = value
    return max_value

if __name__ == ""__main__"":
    parser = argparse.ArgumentParser(description=""Find the largest integer from a CSV file."")
    parser.add_argument(""input"", help=""Input CSV file"")
    parser.add_argument(""-o"", ""--output"", help=""Output file to write result"")
    parser.add_argument(""-c"", ""--compact"", action='store_true', 
                        help=""Compact output (only print the maximum value)"")

    args = parser.parse_args()

    data = read_csv(args.input)
    max_value = find_maximum(data)

    if args.output:
        try:
            with open(args.output, ""w"") as file:
                if args.compact:
                    file.write(str(max_value))
                else:
                    file.write(""The largest integer in the CSV file is: "" + str(max_value) + ""\n"")
        except Exception as e:
            print(f""Error occurred while writing to output file: {e}"")
    else:
        if args.compact:
            print(max_value)
        else:
            print(""The largest integer in the CSV file is: "" + str(max_value))
