# DataEncryptor.py 
from cryptography.fernet import Fernet

class DataEncryptor(object):
    def __init__(self, key=None):
        self._key = Fernet.generate_key() if key is None else key
        self._cipher_suite = Fernet(self._key)

    def encrypt(self, data):
        cipher_text = self._cipher_suite.encrypt(data)
        return cipher_text

    def decrypt(self, encrypted_data):
        plain_text = self._cipher_suite.decrypt(encrypted_data)
        return plain_text
```

Now let's implement SecureUserDatabase:

```python
import json
from DataEncryptor import DataEncryptor

class SecureUserDatabase():
    def __init__(self):
        self.database = {}

    def generateKey(self):
        return Fernet.generate_key()

    def encryptData(self, data, key=None):
        if not key:
            key = self.generateKey()
        dataEncrytor = DataEncryptor(key)
        encrypted_data = dataEncrytor.encrypt(json.dumps(data).encode())
        return (encrypted_data, key)

    def storeUser(self, userID, data):
        encrypted_data, key = self.encryptData(data)
        self.database[userID] = { 'key': key, 'data': encrypted_data }

    def retrieveUser(self, userID):
        if userID in self.database:
            encrypted_data = self.database[userID]['data']
            key = self.database[userID]['key']
            dataEncrytor = DataEncryptor(key)
            return json.loads(dataEncrytor.decrypt(encrypted_data))
        else:
            print(""User not found."")

    def createUsers(self, numberOfUsers):
        users = []
        for i in range(numberOfUsers):
            userID = 'user'+str(i)
            data = {'id': userID, 'name': 'User_' + str(i), 'status': 'active'}
            self.storeUser(userID, data)

        return users
```

