        return ''.join(random.choices(string.digits + 'ABCD', k=15))

    def create_imsi():
        return '46000' + ''.join(random.choices(string.digits, k=9))

    def create_subscription_id():
        return ''.join(random.choices(string.ascii_letters + string.digits, k=10))

    def create_user_agent():
        browsers = [""Chrome"", ""Firefox"", ""Safari"", ""Edge"", ""Opera""]
        os = [""Windows"", ""MacOS"", ""Linux""]
        return f""{random.choice(browsers)}/{random.randint(1, 99)}.x ({random.choice(os)})""

    session_info_list = []

    for _ in range(num_sessions):
        imei = create_imei()
        imsi = create_imsi()
        subscription_id = create_subscription_id()

        device_id = hashlib.sha256(f""{imei}{imsi}"".encode()).hexdigest()

        user_agent = create_user_agent()

        session_info_list.append(TNSessionInfo(imei=imei, imsi=imsi, subscription_id=subscription_id,
                                              user_agent=user_agent, device_id=device_id))

    return session_info_list
