```",680,,"['Here's a possible implementation of the requested features. I used Python's built-in csv module for writing to text files and sorted function with a lambda function as key argument to sort `SONG_INFORMATION_T` structures by release year. The error handling is performed using try/except blocks and random module to generate unique song names:

```python
import random
import os
import csv
from datetime import date

class SongInformation:
    def __init__(self, id, title, release_year, genre):
        self.id = id
        self.title = title
        self.release_year = release_year
        self.genre = genre

def validate_song_info(song):
    try:
        if not 1 <= song.id <= 1000 or not 1900 <= song.release_year <= date.today().year:
            return False
        return True
    except TypeError as te:
        print(""Invalid input parameters: "", te)
        return False

def sort_songs_by_release(songs):
    try:
        return sorted(songs, key=lambda song: song.release_year)
    except Exception as e:
        print('An error occurred while sorting songs by release year:', e)
        return []

def save_songs_to_file(filename, songs):
    try:
        with open(filename, 'w') as file:
            writer = csv.writer(file)
            for song in songs:
                writer.writerow([song.id, song.title, song.release_year, song.genre])
    except Exception as e:
        print('An error occurred while saving songs to file:', e)

def generate_random_song():
    try:
        return SongInformation(
            random.randint(1, 1000),
            ''.join(chr(random.choice((65, 97))) for _ in range(10)),
            random.randint(1900, date.today().year),
            chr(random.choice((65, 97))),
        )
    except Exception as e:
        print('An error occurred while generating a song:', e)

def create_and_save_song_batches(num_batches, filenames):
    try:
        for i in range(num_batches):
            songs = [generate_random_song() for _ in range(10)]
            sorted_songs = sort_songs_by_release(songs)
            save_songs_to_file(filenames[i], sorted_songs)
    except Exception as e:
        print('An error occurred while creating and saving song batches:', e)
``` 

This code can be further improved by adding more specific exceptions, checking if the filenames are valid before trying to open them or checking the genre type.
