import requests
from typing import Dict, List, Any

class ProductFetcher:
    def __init__(self, api_key: str) -> None:
        self.api_key = api_key
        self.product_details: Dict[int, Dict[str, Any]] = {}  # Cache for fetched products

    def fetch_product(self, product_id: int) -> Dict[str, Any]:
        url = f""https://api.example.com/products/{product_id}""
        headers = {""Authorization"": f""Bearer {self.api_key}""}

        try:
            response = requests.get(url, headers=headers)
            response.raise_for_status()

            product_data = response.json()
            self.product_details[product_id] = product_data
            return product_data

        except requests.RequestException as e:
            raise Exception(f""Failed to fetch product data: {e}"")

    def get_product_details(self, product_id: int) -> Dict[str, Any]:
        return self.product_details.get(product_id)

class OnlineStore:
    def __init__(self, products_api_key: str) -> None:
        self.products_api_key = products_api_key
        self.shopping_cart: List[Dict[str, Any]] = []

    def add_product(self, product_id: int) -> bool:
        if not isinstance(product_id, int) or product_id <= 0:
            raise ValueError(""Invalid product ID"")

        fetched_product = ProductFetcher(self.products_api_key).fetch_product(product_id)

        if not fetched_product:
            print(""Product not found"")
            return False

        self.shopping_cart.append(fetched_product)
        return True

    def view_cart(self) -> None:
        total_cost = 0.0
        for item in self.shopping_cart:
            total_cost += item['price']

        print(""Shopping Cart:"")
        for index, item in enumerate(self.shopping_cart):
            print(f""{index + 1}. {item['name']} - ${item['price']}"")

        print(f""Total cost: ${total_cost:.2f}"")

