def advanced_dict_operations(initial_data, operations):
    modified_dict = initial_data.copy()

    # Case-insensitive handling
    for op_type, key_to_operate_on_lowered_case, *args in map(lambda op: (op[0], op[1].lower(), 
                                                                         *op[2:]) if isinstance(op[1], str) else op, operations):
        # Check for correct operation types and parameter count
        if op_type not in ['add', 'remove', 'update']:
            raise ValueError(f""Invalid operation '{op_type}'"")

        if op_type == ""add"":
            if len(args) > 1:
                raise ValueError(""Only one argument expected for add operation"")
            else:
                modified_dict[key_to_operate_on_lowered_case] = args[0]

        elif op_type == ""remove"":
            if len(args) > 1:
                raise ValueError(""Only one argument expected for remove operation"")
            else:
