def generate_sensor_reading(sensor_type):
    if sensor_type == 'temperature':
        return random.uniform(20.0, 30.0)
    elif sensor_type == 'humidity':
        return random.uniform(45.0, 65.0)
    else:
        raise ValueError(""Invalid sensor type"")

def create_iot_device(sensor_type):
    reading = generate_sensor_reading(sensor_type)
    timestamp = int(time.time())

    nccp_structure = create_nccp_structure()

    return {
        'sensorType': sensor_type,
        'measuredValue': reading,
        'timestamp': timestamp,
        'macAddress': nccp_structure['macAddress'],
        'ipAddress': nccp_structure['ipAddress'],
        'port': nccp_structure['port']
    }

def create_nccp_structure():
    mac_address = generate_unique_mac()
    ip_address = generate_unique_ip(mac_address)
    port = generate_unique_port()

    return {
        'macAddress': mac_address,
        'ipAddress': ip_address,
        'port': port
    }

def generate_unique_mac():
    while True:
        new_mac = EUI(struct.pack('>Q', random.getrandbits(48)))
        if str(new_mac) not in existing_devices:
            existing_devices.add(str(new_mac))
            return mac_unix_expanded(str(new_mac), dashsep=2, groupsep=':')  # format as xx:xx:xx:xx:xx:xx

def generate_unique_ip(mac):
    while True:
        new_ip = '.'.join(map(str, (random.randint(0, 255) for _ in range(4))))
         # Check if IP address is within reserved or private network ranges
        first_octet = int(new_ip.split('.')[0])
        if not (first_octet == 10 or first_octet == 192 and int(new_ip.split('.')[1]) == 168):
            # Check if IP address is being used by any existing MAC addresses
            if new_ip not in [device['ipAddress'] for device in devices]:
                return new_ip

def generate_unique_port():
    while True:
        port = random.randint(1024, 65535) # non-privileged ports range from 1024 to 65535
        if not is_port_in_use(port):
            return port

def is_port_in_use(port):
    for device in devices:
        if device['port'] == port:
            return True
    return False

# Generate IoT sensor data and network structure management
devices = [create_iot_device('temperature') for _ in range(10)] # generate 10 devices with temperature sensors
